    return s


rw(E + 'ErrorBackgroundEvent.java', err)

for f in ['DefaultBackgroundThread.java', 'DefaultEventHandler.java', 'ErrorEventHandler.java', E + 'EventHandler.java',
          E + 'NoopApplicationEvent.java', E + 'NoopBackgroundEvent.java']:
    os.remove(D + f)

