import os
import shutil

T = 'clients/src/test/java/org/apache/kafka/clients/consumer/internals/'
lic = open('clients/src/main/java/org/apache/kafka/clients/consumer/internals/RequestManager.java', encoding='utf-8', newline='').read().split('package ')[0]

for root, _, files in os.walk('.scratch/newtests'):
    for f in files:
        src = os.path.join(root, f)
        rel = os.path.relpath(src, '.scratch/newtests').replace('\\', '/')
        dst = T + rel
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        s = open(src, encoding='utf-8', newline='').read()
        if not s.startswith('/*'):
            s = lic + s
        open(dst, 'w', encoding='utf-8', newline='').write(s)
        print('installed', dst)


def append_methods(f, methods, imports=(), static_imports=()):
    p = T + f
    s = open(p, encoding='utf-8', newline='').read()
    s = s.rstrip('\n')
    assert s.endswith('}')
    s = s[:-1].rstrip('\n') + '\n\n' + methods.strip('\n') + '\n}\n'
    for imp in imports:
        line = 'import %s;\n' % imp
        if line not in s:
            # insert before first blank line following the last non-static import
            idx = s.index('\nimport java.') if '\nimport java.' in s else s.index('\nimport static')
            s = s[:idx] + '\n' + line.rstrip('\n') + s[idx:]
    for imp in static_imports:
        line = 'import static %s;\n' % imp
        if line not in s:
            idx = s.index('\nimport static')
            s = s[:idx] + '\n' + line.rstrip('\n') + s[idx:]
    open(p, 'w', encoding='utf-8', newline='').write(s)


